solution.solution.py:
def format_price(amount, currency="€", decimals=2, *, thousands=False):
    spec = f",.{decimals}f" if thousands else f".{decimals}f"
    return f"{amount:{spec}} {currency}"


def average(*numbers):
    if not numbers:
        return None
    return sum(numbers) / len(numbers)


def merged(defaults, **overrides):
    result = dict(defaults)
    result.update(overrides)
    return result


def add_tag(tag, tags=None):
    if tags is None:
        tags = []
    tags.append(tag)
    return tags

unitTests:
@test("prices")
def _():
    check_eq(format_price(1234.5), "1234.50 €")
    check_eq(format_price(1234.5, "$", 0), "1234 $")
    check_eq(format_price(1234.5, thousands=True), "1,234.50 €")
    check_eq(format_price(9.999, decimals=1), "10.0 €")
    check_raises(TypeError, format_price, 5, "€", 2, True)

@test("averages")
def _():
    check_eq(average(1, 2, 3, 4), 2.5)
    check_eq(average(), None)
    check_eq(average(*[10, 20]), 15.0)

@test("merging")
def _():
    defaults = {"size": 12, "theme": "dark"}
    result = merged(defaults, size=14, wrap=True)
    check_eq(result, {"size": 14, "theme": "dark", "wrap": True})
    check_eq(defaults, {"size": 12, "theme": "dark"})

@test("no shared default")
def _():
    check_eq(add_tag("a"), ["a"])
    check_eq(add_tag("b"), ["b"])
    mine = ["x"]
    check(add_tag("y", mine) is mine, "a list that is passed in is used")
    check_eq(mine, ["x", "y"])

